// settings.gradle.kts 의 repositories 에 mavenCentral() 이 있으면 된다 — 별도 저장소는 필요 없다.
// 앱 minSdk 는 37(Android 17) 이상이어야 한다 — SDK 최소 사양이다.
dependencies {
    implementation("com.ones1ght.sdk:android:0.0.3")
}

steps.code:
// RANGING + ACCESS_FINE_LOCATION + BLUETOOTH_SCAN(+ 함께 묻는 ACCESS_COARSE_LOCATION)을 한 번에 요청한다.
// 대략 위치만 허용하거나 근처 기기(BLE)를 거부하면 DENIED 다 — 측위에는 정밀 위치와 BLE 스캔(층 탐지)이 필요하다.
// activityResultRegistry 를 쓰므로 onCreate 이후 아무 때나 불러도 된다.
when (OneS1ght.permissions(activity)) {
    PermissionStatus.AUTHORIZED  -> { /* 측위 시작 가능 */ }
    PermissionStatus.DENIED      -> showSettingsGuide()      // 30초 무응답도 DENIED
    PermissionStatus.UNSUPPORTED -> showUnsupportedNotice()
}

