val session = OneS1ght.floorSession()

session.onConfigChanged = ConfigChangeListener { change ->
    // 콘솔에서 구역·도면·시책이 바뀌면 온다 — 측위 중에만 붙어 있다
    reloadOverlay(change)
}

// 네트워크를 타지 않고 기다리지도 않는다. initialize 다음에 읽는다 — 그 전에는 판단할 수 없어 DEVICE_NOT_SUPPORTED 다.
when (OneS1ght.deviceAvailability) {
    DeviceAvailability.AVAILABLE            -> { }
    DeviceAvailability.OS_VERSION_TOO_LOW   -> showNotice("Android 17 이상이 필요합니다")
    DeviceAvailability.DEVICE_NOT_SUPPORTED -> hidePositioningFeatures()
}

if (BuildConfig.DEBUG) {
    OneS1ght.onDebugLog = DebugLogListener { level, message -> Log.d("OneS1ght", "[$level] $message") }
}
